using LlmObservability.Web.Services;

namespace LlmObservability.Web.Models;

public class DashboardViewModel
{
    // Natural language query
    public string? NaturalLanguageQuery { get; set; }
    public string? Explanation { get; set; }

    // OData query parameters generated by Claude
    public string? ODataUrl { get; set; }
    public string? FilterExpression { get; set; }
    public string? OrderBy { get; set; }
    public int?    Top { get; set; }
    public string? Expand { get; set; }
    public string? Apply { get; set; }

    // Phrase searches and the synonym variants they were expanded to
    public List<TextSearchInfo> TextSearches { get; set; } = [];

    // Live OData results fetched from the API
    public List<Dictionary<string, string>>? QueryResults { get; set; }
    public int? QueryResultCount { get; set; }

    public string? ModelProvider { get; set; }

    // Translators the API offers (Claude, Microsoft Foundry), with model names and whether they're configured
    public List<ProviderInfo> Providers { get; set; } = [];

    public ProviderInfo SelectedProvider =>
        Providers.FirstOrDefault(p => p.Id == ModelProvider)
        ?? Providers.FirstOrDefault()
        ?? new ProviderInfo("anthropic", "Claude", "", true);

    public string? ErrorMessage { get; set; }

    public bool HasQueryResult =>
        !string.IsNullOrEmpty(FilterExpression)
        || !string.IsNullOrEmpty(OrderBy)
        || Top.HasValue
        || !string.IsNullOrEmpty(Expand)
        || !string.IsNullOrEmpty(Apply);
}
